// EDIT: your permissioned sources. channel_id starts with UC...
const sources = [
  { name: 'ExampleStreamer', channel_id: 'UCxxxxxxxxxxxxxxxxxxxxxx' }
];
return sources.map(s => ({ json: { ...s, feed: 'https://www.youtube.com/feeds/videos.xml?channel_id=' + s.channel_id } }));

const store = $getWorkflowStaticData('global');
store.seen = store.seen || [];
const src = $('Sources').all();
const maxAgeMs = 72 * 3600 * 1000;
const kw = /gta\s*(6|vi)\b|grand theft auto\s*(6|vi)\b|leonida/i;
const skip = /leak|pre-?release/i;
const out = [];
$input.all().forEach((it, i) => {
  const xml = typeof it.json.data === 'string' ? it.json.data : JSON.stringify(it.json);
  const channel = src[i] ? src[i].json.name : 'unknown';
  for (const m of xml.matchAll(/<entry>([\s\S]*?)<\/entry>/g)) {
    const e = m[1];
    const id = (e.match(/<yt:videoId>([^<]+)</) || [])[1];
    const title = ((e.match(/<title>([^<]*)</) || [])[1] || '').replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"');
    const pub = Date.parse((e.match(/<published>([^<]+)</) || [])[1]);
    if (!id || store.seen.includes(id) || !kw.test(title) || skip.test(title) || Date.now() - pub > maxAgeMs) continue;
    store.seen.push(id);
    out.push({ json: { id, title, channel, url: 'https://www.youtube.com/watch?v=' + id } });
  }
});
store.seen = store.seen.slice(-2000);
return out;
